// Cross-language parity with spec/vectors.json (§20), generated by spec/gen_vectors.py.
// Skipped until the Python side (issue #11) commits vectors.json.
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import {
  canonicalOf,
  digestOf,
  SCHEMAS,
  verifyDigest,
  type Dlog,
  type SchemaType,
} from '..';

interface Vector {
  name: string;
  type: string;
  fields: Record<string, unknown>;
  canonical?: string;
  digest?: string;
  pub?: string;
  sig?: string;
  valid?: boolean;
}

const PATH = resolve(__dirname, '../../../../spec/vectors.json');
const raw: unknown = existsSync(PATH) ? JSON.parse(readFileSync(PATH, 'utf8')) : null;
const vectors: Vector[] = Array.isArray(raw) ? raw : ((raw as { vectors?: Vector[] } | null)?.vectors ?? []);
const objectVectors = vectors.filter((v) => v.type in SCHEMAS || v.type === 'DLOG');

describe.skipIf(!raw)('spec/vectors.json', () => {
  it.each(objectVectors.map((v) => [v.name, v] as const))('%s', (_name, v) => {
    const s =
      v.type === 'DLOG'
        ? canonicalOf('DLOG', v.fields as unknown as Dlog)
        : canonicalOf(v.type as SchemaType, v.fields);
    if (v.canonical !== undefined) expect(s).toBe(v.canonical);
    if (v.digest !== undefined) expect(digestOf(s)).toBe(v.digest);
    if (v.sig && v.pub) expect(verifyDigest(v.sig, digestOf(s), v.pub)).toBe(v.valid ?? true);
  });
});
